    Check(!FYApplyInlineBatchResults(@[@"部分"],2,@[@2,@1],@[@"b",@"a"],outputs,cacheWrite) && [outputs[2] isEqual:@"部分"] && [outputs[1] isEqual:@""],@"partial nonblank batch retains existing acceptance rule");
    NSString *paragraph=@"这是一段超过二十四个字符的重复段落用于验证不完整批次拒绝策略。";
    outputs=[@[@"",@"",@""] mutableCopy]; [written removeAllObjects];
    Check(FYApplyInlineBatchResults(@[paragraph],3,@[@0,@1,@2],@[@"a",@"b",@"c"],outputs,cacheWrite).code==205 && written.count==0,@"incomplete repeated paragraph rejected before caching");
    Check(!FYApplyInlineBatchResults(@[paragraph,paragraph,paragraph],3,@[@0,@1,@2],@[@"a",@"b",@"c"],outputs,cacheWrite),@"complete batch does not gain new duplicate rejection behavior");
    for (NSUInteger order=0;order<2;order++) {
        __block void (^shortDone)(NSError *), (^longDone)(NSError *);
        __block NSUInteger calls=0; __block NSError *received=nil;
