        FYRunInlineBatches(YES,YES,outputs,^(BOOL longText,void (^done)(NSError *)){ if(longText)longDone=done; else shortDone=done; },^(NSArray *values,NSError *error){ calls++;received=error;Check(values==nil,@"batch error suppresses translated array"); });
